window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[293]={"id":"293","numero":293,"titre":"Médecin préleveur de cellules et/ou de tissus","objectifs":[{"id":"293-1","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les modalités de réalisation d’un prélèvement cellulaire ou tissulaire pour études morphologiques et moléculaires","contenu":"<p>Un prélèvement adressé en <span class=\"kw-def\">Anatomie et Cytologie Pathologiques (ACP)</span> est soit <span class=\"kw-def\">cytologique</span> (étude des <strong>cellules isolées</strong>), soit <span class=\"kw-def\">histologique</span> (étude des <strong>tissus</strong>). La modalité de réalisation et le <span class=\"kw-def\">conditionnement initial</span> (fixation ou état frais) sont décidés par le préleveur <strong>avant</strong> l'acheminement.</p>\n      <table >\n        <thead><tr><th>Type</th><th>Modalités de réalisation</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Cytologie</span><br>(cellules isolées)</td>\n            <td>\n              <strong>Liquides émis spontanément :</strong> <span class=\"kw-clinique\">urines</span> ; <span class=\"kw-clinique\">expectorations</span><br>\n              <strong>Recueil dirigé :</strong> <span class=\"kw-clinique\">frottis</span> ; <span class=\"kw-clinique\">écouvillonnage</span> ; <span class=\"kw-clinique\">aspiration</span> (<span class=\"kw-clinique\">LBA</span>, <span class=\"kw-clinique\">bulle</span> cutanée)<br>\n              <strong><span class=\"kw-ttt\">Ponction</span> à l'aiguille d'un liquide :</strong> <span class=\"kw-clinique\">LCR</span> ; épanchement d'une séreuse<br>\n              <strong>Cytoponction d'organes pleins :</strong> <span class=\"kw-clinique\">ganglion</span> ; <span class=\"kw-clinique\">thyroïde</span> ; <span class=\"kw-clinique\">foie</span>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Histologie</span><br>(tissus)</td>\n            <td>\n              <strong>Pièce opératoire :</strong> <span class=\"kw-ttt\">exérèse</span> <strong>partielle</strong> ou <strong>complète</strong> d'une tumeur ou d'un organe<br>\n              <strong><span class=\"kw-ttt\">Biopsie</span> :</strong> prélèvement d'un <strong>fragment</strong> de tissu <span class=\"kw-etio\">tumoral</span>, <span class=\"kw-alerte\">hors zone de nécrose</span> et en <strong>nombre suffisant</strong>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p>Quelle que soit la technique, deux <strong>conditionnements</strong> sont possibles juste après le geste :</p>\n      <ul>\n        <li><strong><span class=\"kw-def\">Fixation</span> :</strong> immersion dans du <span class=\"kw-bio\">formol dilué tamponné</span> — empêche l'<span class=\"kw-alerte\">autolyse</span> du tissu (cas standard).</li>\n        <li><strong><span class=\"kw-def\">État frais</span> (sans fixateur) :</strong> indiqué pour l'<span class=\"kw-bio\">examen extemporané</span>, la recherche de <span class=\"kw-bio\">graisses</span>, l'<span class=\"kw-bio\">immunofluorescence directe</span> et la <span class=\"kw-bio\">cryopréservation</span> <span class=\"kw-etio\">tumorale</span> (voir obj. dédiés).</li>\n      </ul>\n      <div class=\"callout callout-warn\">⚠️ Un prélèvement <strong>non fixé</strong> doit parvenir au laboratoire en <span class=\"kw-chiffre\">&lt; 30 minutes</span> pour éviter l'<span class=\"kw-alerte\">autolyse</span> et la <span class=\"kw-alerte\">dessiccation</span>.</div>","frequence":3},{"id":"293-2","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les modalités de transmission des prélèvements cellulaires et tissulaires pour études morphologiques et moléculaires","contenu":"<p>Tout prélèvement est acheminé au laboratoire d'ACP avec deux éléments <strong>indissociables</strong> : l'<span class=\"kw-def\">identification du patient</span> sur le contenant et une <span class=\"kw-def\">feuille de demande / fiche de renseignements</span> (indispensable — elle n'accompagne jamais l'analyse, elle la conditionne). Le <strong>mode de conditionnement</strong> détermine ensuite le délai de transmission acceptable.</p>\n      <table >\n        <thead><tr><th>Modalité</th><th>Mise en œuvre</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Transmission</span></td>\n            <td>\n              <span class=\"kw-clinique\">Identification du patient</span> sur le contenant<br>\n              <span class=\"kw-def\">Fiche de renseignements</span> jointe (impérative)\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Fixation</span></td>\n            <td>\n              Immersion dans du <span class=\"kw-bio\">formol dilué, tamponné</span> → empêche l'<span class=\"kw-alerte\">autolyse</span><br>\n              Si <strong>absence de fixation</strong> : acheminement en <span class=\"kw-chiffre\">&lt; 30 minutes</span> (éviter autolyse / dessiccation)\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">État frais</span><br>(sans fixateur)</td>\n            <td>\n              <span class=\"kw-bio\">Examen extemporané</span><br>\n              Recherche de <span class=\"kw-bio\">graisses</span> dans le tissu (la paraffine les dissout)<br>\n              <span class=\"kw-bio\">Immunofluorescence directe</span> (<span class=\"kw-ttt\">biopsie</span> cutanée, rénale, typage d'amylose)<br>\n              <span class=\"kw-bio\">Cryopréservation</span> <span class=\"kw-etio\">tumorale</span> à but sanitaire : <span class=\"kw-etio\">tumeur pédiatrique</span>, <span class=\"kw-etio\">suspicion de lymphome</span>, <span class=\"kw-etio\">sarcome</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">📌 Toujours <strong>préciser le type d'analyse souhaité</strong> sur la demande (ex. : LBA avec analyse <span class=\"kw-def\">anatomopathologique</span> <strong>+</strong> bactériologique, parasitologique et mycologique) — un même prélèvement peut être réparti entre plusieurs laboratoires.</div>","frequence":2},{"id":"293-3","rang":"A","rubrique":"Examens complémentaires","titre":"Savoir remplir la fiche de renseignements","contenu":"<p>La <span class=\"kw-def\">fiche de renseignements</span> est <strong>obligatoire</strong> et accompagne tout prélèvement. Elle ne contient <strong>aucune analyse</strong> : elle fournit au <span class=\"kw-def\">pathologiste</span> les informations <span class=\"kw-alerte\">indispensables à l'interprétation</span>. Items à renseigner :</p>\n      <ul>\n        <li><strong>Identité du patient :</strong> nom, prénom, <span class=\"kw-clinique\">date de naissance</span>, <span class=\"kw-clinique\">sexe</span>, adresse et/ou identifiant hospitalier.</li>\n        <li><strong>Identité du médecin <span class=\"kw-def\">prescripteur</span> :</strong> nom, prénom, structure de soin et service, identifiants professionnels.</li>\n        <li><strong>Identité du <span class=\"kw-def\">préleveur</span> :</strong> peut <strong>différer</strong> du prescripteur (mêmes informations que ce dernier).</li>\n        <li><strong>Caractère <span class=\"kw-alerte\">urgent</span></strong> éventuel de la demande.</li>\n        <li><strong><span class=\"kw-clinique\">Date</span> et <span class=\"kw-clinique\">heure</span> du prélèvement</strong>, <span class=\"kw-def\">nature</span> du prélèvement, <span class=\"kw-clinique\">siège</span> du ou des <span class=\"kw-bio\">échantillons</span>.</li>\n        <li><strong><span class=\"kw-clinique\">Renseignements cliniques</span> pertinents</strong> (orientent l'<span class=\"kw-alerte\">interprétation</span> morphologique).</li>\n        <li><strong><span class=\"kw-bio\">Recherches particulières</span> demandées</strong> (ex. : technique ou <span class=\"kw-bio\">marqueur</span> ciblé).</li>\n      </ul>\n      <div class=\"callout callout-info\">📌 Toujours préciser <strong>quel type d'analyse</strong> est souhaité sur le prélèvement (ex. : <span class=\"kw-clinique\">biopsie</span> avec examen <span class=\"kw-def\">anatomopathologique</span>), pour orienter le tri et le conditionnement au laboratoire.</div>","frequence":1},{"id":"293-4","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les principes de base de réalisation et d’interprétation des techniques morphologiques","contenu":"<p>Les <span class=\"kw-def\">techniques morphologiques</span> reposent sur la <strong>coloration</strong> de cellules ou de coupes tissulaires, examinées au microscope. Trois grandes familles : <span class=\"kw-def\">cytologie</span>, <span class=\"kw-def\">histologie</span> et <span class=\"kw-def\">immunohistochimie / immunocytochimie</span>.</p>\n      <table >\n        <thead><tr><th>Technique</th><th>Principe</th><th>Délai</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Cytologie</span></td>\n            <td>\n              Cellules <span class=\"kw-bio\">fixées</span> (alcool, séchage à l'air, laque) ou <strong>étalées en monocouche</strong> au laboratoire, puis <span class=\"kw-bio\">réhydratées</span> et <span class=\"kw-bio\">colorées</span>.<br>\n              Ne donne qu'une <span class=\"kw-alerte\">orientation diagnostique</span> ++ (souvent confirmée par l'<span class=\"kw-bio\">histologie</span>).\n            </td>\n            <td><span class=\"kw-chiffre\">Rapide</span><br>(pas d'inclusion)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Histologie</span></td>\n            <td>\n              <strong>1.</strong> <span class=\"kw-bio\">Fixation</span> au <span class=\"kw-bio\">formol dilué à 10 %</span>, tamponné.<br>\n              <strong>2.</strong> <span class=\"kw-bio\">Macroscopie</span> des pièces volumineuses (<span class=\"kw-chiffre\">+ 1 jour</span>).<br>\n              <strong>3.</strong> <span class=\"kw-bio\">Inclusion en paraffine</span> : déshydratation par alcools, xylène (<span class=\"kw-alerte\">dissout les graisses</span>), enrobage (<span class=\"kw-chiffre\">1 jour</span>).<br>\n              <strong>4.</strong> <span class=\"kw-bio\">Coupe</span> à <span class=\"kw-chiffre\">3–4 µm</span>, étalement, déparaffinage, <strong>coloration</strong> et montage.<br>\n              <strong>Coloration standard :</strong> <span class=\"kw-bio\">HE</span> (hématoxyline–éosine) ou <span class=\"kw-bio\">HES</span> (+ safran).\n            </td>\n            <td><span class=\"kw-chiffre\">1–2 jours</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Immunohistochimie</span><br><span class=\"kw-def\">Immunocytochimie</span></td>\n            <td>\n              <strong>But :</strong> identifier et localiser des <span class=\"kw-bio\">protéines</span> par leurs propriétés antigéniques, sur lames « blanches ».<br>\n              <strong>Direct :</strong> anticorps couplé directement au <span class=\"kw-bio\">fluorochrome</span> ou à l'<span class=\"kw-bio\">enzyme</span>.<br>\n              <strong>Indirect :</strong> anticorps primaire révélé par un <strong>2ᵉ anticorps</strong> couplé.<br>\n              <strong>IF directe :</strong> dépôts d'<span class=\"kw-bio\">immunoglobulines</span> / <span class=\"kw-bio\">complément</span> sur biopsies cutanées et rénales <strong>congelées</strong> (microscope à fluorescence).<br>\n              <strong>Méthode immuno-enzymatique :</strong> diagnostic de <span class=\"kw-etio\">lésion tumorale</span> (microscope à fond clair).\n            </td>\n            <td><span class=\"kw-chiffre\">+ 1 jour</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Interprétation et compte-rendu.</strong> Les lames sont examinées par le médecin <span class=\"kw-def\">anatomopathologiste</span> ; le résultat est diffusé dans un <span class=\"kw-def\">compte-rendu écrit</span> en terminologie médicale, avec les <strong>données minimales</strong> essentielles à la prise en charge des pathologies tumorales. Les <span class=\"kw-bio\">lames</span> et <span class=\"kw-bio\">blocs</span> de paraffine sont <strong>archivés</strong> (études complémentaires ou recherche ultérieures possibles).</p>\n      <div class=\"callout callout-warn\">⚠️ <strong>Double lecture systématisée</strong> par les réseaux nationaux de référence (<span class=\"kw-def\">INCa</span>) pour : <span class=\"kw-etio\">sarcomes</span>, <span class=\"kw-etio\">lymphomes</span>, <span class=\"kw-etio\">mésothéliomes</span>, <span class=\"kw-etio\">tumeurs neuroendocrines rares</span>.</div>\n      <div class=\"callout callout-info\">📚 <strong>Terminologie des comptes-rendus tumoraux (QCM ++)</strong>\n        <ul>\n          <li><strong><span class=\"kw-def\">Dysplasie</span> épithéliale :</strong> synonyme de <span class=\"kw-def\">néoplasie intra-épithéliale</span>, décrite <strong>uniquement dans les épithéliums</strong> ; <span class=\"kw-alerte\">lésion précancéreuse</span> non invasive (pas de franchissement de la membrane basale). Classée en <strong>bas / haut <span class=\"kw-def\">grade</span></strong> (la dysplasie sévère est très proche du cancer).</li>\n          <li><strong><span class=\"kw-def\">Tumeur</span> = <span class=\"kw-def\">néoplasie</span> :</strong> prolifération cellulaire anormale et <strong>autonome</strong> (échappe aux régulations).</li>\n          <li><strong><span class=\"kw-def\">Métaplasie</span> :</strong> transformation d'un tissu normal en un autre tissu normal — <strong>non <span class=\"kw-etio\">tumorale</span></strong>, mais peut le devenir (séquence métaplasie / dysplasie / cancer).</li>\n          <li><strong><span class=\"kw-def\">Hyperplasie</span> :</strong> ↑ du nombre de cellules, <strong>contrôlée et réversible</strong> (non <span class=\"kw-etio\">tumorale</span>).</li>\n          <li><strong><span class=\"kw-def\">Polype</span> :</strong> saillie à la surface d'une muqueuse — <strong>ne préjuge pas</strong> de la nature de la <span class=\"kw-clinique\">lésion</span>.</li>\n          <li><strong><span class=\"kw-def\">Hamartome</span> :</strong> mélange anormal de cellules normalement présentes dans l'organe.</li>\n        </ul>\n      </div>\n      <div class=\"callout callout-danger\">⚠️ Le <strong>cancer est toujours de haut <span class=\"kw-def\">grade</span></strong> — ne pas le confondre avec la gradation de la dysplasie.</div>","frequence":2},{"id":"293-5","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les techniques de biologie moléculaire sur les prélèvements tissulaires/cellulaires","contenu":"<p>Les techniques de <span class=\"kw-def\">biologie moléculaire</span> recherchent une <span class=\"kw-bio\">séquence d'acide nucléique</span> (ADN ou ARN) à visée <strong>diagnostique</strong>, <strong>pronostique</strong> et <strong>théranostique</strong>. Deux grandes approches : l'<span class=\"kw-def\">hybridation in situ</span> (morphologique) et la <span class=\"kw-def\">biologie moléculaire non morphologique</span>.</p>\n      <table >\n        <thead><tr><th>Technique</th><th>Principe &amp; applications</th><th>Délai</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Hybridation in situ</span><br>(<span class=\"kw-bio\">FISH</span> / <span class=\"kw-bio\">CISH</span>)</td>\n            <td>\n              <strong>Sondes nucléiques</strong> fixant la cible par complémentarité des bases, couplées à un traceur :<br>\n              <strong><span class=\"kw-bio\">FISH</span> :</strong> fluorochrome (microscope à fluorescence)<br>\n              <strong><span class=\"kw-bio\">CISH</span> :</strong> enzyme (microscope à fond clair)<br>\n              <strong>Exemples :</strong> amplification <span class=\"kw-etio\">HER2</span> (sein, estomac → anti-HER2) ; réarrangement <span class=\"kw-etio\">ALK</span> (poumon → anti-ALK)\n            </td>\n            <td><span class=\"kw-chiffre\">1–2 jours</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Biologie moléculaire</span><br>non morphologique</td>\n            <td>\n              <strong>But :</strong> clonalité, perte d'hétérozygotie, <span class=\"kw-bio\">mutations</span>, réarrangements.<br>\n              <strong>Déroulement :</strong> extraction d'ADN/ARN → <span class=\"kw-bio\">amplification PCR</span> → <span class=\"kw-bio\">séquençage</span> (Sanger, <span class=\"kw-bio\">NGS</span>).<br>\n              <strong>Exemples théranostiques :</strong> <span class=\"kw-etio\">BRAF V600</span> (<span class=\"kw-clinique\">mélanome</span>), <span class=\"kw-etio\">EGFR</span> (poumon), <span class=\"kw-etio\">KRAS / NRAS</span> (côlon → résistance anti-EGFR).\n            </td>\n            <td><span class=\"kw-chiffre\">Plusieurs jours</span><br>(plateforme experte)</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Type de prélèvement.</strong> Réalisable sur cellules sur lames, culot cellulaire, prélèvement <span class=\"kw-bio\">congelé</span> à <span class=\"kw-chiffre\">– 80 °C</span> (<strong>au mieux</strong>) ou tissu <span class=\"kw-bio\">fixé au formol et inclus en paraffine</span> (majorité des cas, fixation <span class=\"kw-chiffre\">6–24 h</span>).</p>\n      <p><strong>Contrôle morphologique préalable systématique</strong> : éviter les <span class=\"kw-alerte\">zones de nécrose</span> et vérifier un taux de <span class=\"kw-bio\">cellules tumorales</span> <span class=\"kw-chiffre\">&gt; 25–30 %</span> (sinon faux négatifs).</p>\n      <div class=\"callout callout-warn\">⚠️ Sur tissu <strong>fixé au formol</strong>, l'<span class=\"kw-bio\">ADN extrait est fragmenté</span> : l'<span class=\"kw-bio\">amplification PCR</span> peut être plus difficile, avec un <span class=\"kw-alerte\">risque d'échec accru</span> de la technique.</div>","frequence":1},{"id":"293-6","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître la définition et les principales indications de l’examen extemporané","contenu":"<p>L'<span class=\"kw-def\">examen extemporané</span> est un <span class=\"kw-def\">examen anatomopathologique</span> réalisé le plus souvent <strong>en cours d'<span class=\"kw-clinique\">intervention chirurgicale</span></strong>, fournissant un résultat en général en <span class=\"kw-chiffre\">&lt; 30 minutes</span>. Il n'est demandé <strong>que si la réponse a une <span class=\"kw-def\">incidence</span> sur la conduite de l'acte en cours</strong>.</p>\n      <p><strong>Principales indications :</strong></p>\n      <ul>\n        <li>Évaluer l'atteinte du <span class=\"kw-clinique\">ganglion sentinelle</span> (<span class=\"kw-etio\">cancer du sein</span>).</li>\n        <li>Déterminer la <strong><span class=\"kw-clinique\">nature tumorale ou non</span></strong> d'une <span class=\"kw-clinique\">lésion</span>.</li>\n        <li>Déterminer la <strong><span class=\"kw-clinique\">nature bénigne ou maligne</span></strong> d'une tumeur.</li>\n        <li>Évaluer les <span class=\"kw-clinique\">limites de résection</span> en cas de pathologie <span class=\"kw-etio\">tumorale</span>.</li>\n        <li>Confirmer qu'un prélèvement a bien intéressé un <strong><span class=\"kw-clinique\">territoire lésionnel représentatif</span></strong> (matériel suffisant).</li>\n      </ul>\n      <p><strong>Technique.</strong> Prélèvement adressé à l'<span class=\"kw-bio\">état frais</span> → <span class=\"kw-bio\">congélation</span> du tissu (<span class=\"kw-chiffre\">– 20 °C</span>) → <span class=\"kw-bio\">coupe au microtome à congélation (cryostat)</span> → <span class=\"kw-bio\">coloration rapide</span>. Méthode cytologique (appositions, liquides) plus rare.</p>\n      <table >\n        <thead><tr><th>Limites</th><th>Conséquence</th></tr></thead>\n        <tbody>\n          <tr><td>Allonge les <span class=\"kw-clinique\">délais opératoires</span></td><td>Temps anesthésique prolongé</td></tr>\n          <tr><td>Coupes de <strong>moindre qualité</strong></td><td>Résultats <span class=\"kw-alerte\">moins précis et moins fiables</span> qu'un examen conventionnel</td></tr>\n          <tr><td>Congélation à <span class=\"kw-chiffre\">– 20 °C</span></td><td><span class=\"kw-alerte\">Abîme le tissu</span> de façon parfois irréversible (gêne un diagnostic ultérieur si matériel exigu)</td></tr>\n          <tr><td>Techniques complémentaires <strong>impossibles</strong></td><td><span class=\"kw-bio\">IHC</span> / biologie moléculaire (<span class=\"kw-chiffre\">1–2 jours</span>) non réalisables en peropératoire</td></tr>\n          <tr><td>Prélèvements <span class=\"kw-bio\">calcifiés</span></td><td>Coupe au cryostat impossible (nécessite une décalcification préalable)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">⚠️ L'avis extemporané <strong>n'est jamais définitif</strong> : il doit <span class=\"kw-alerte\">toujours être vérifié</span> par inclusion en paraffine du tissu restant.</div>","frequence":2},{"id":"293-7","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les tumeurs devant impérativement être adressées à l’état frais au laboratoire d’Anatomie et Cytologie Pathologiques","contenu":"<p>Certaines tumeurs doivent être adressées <strong>sans fixateur, à l'<span class=\"kw-def\">état frais</span></strong>, au <span class=\"kw-def\">laboratoire d'Anatomie et Cytologie Pathologiques</span>, pour permettre une <span class=\"kw-bio\">cryopréservation</span> (<span class=\"kw-bio\">congélation</span> à but sanitaire) du <span class=\"kw-bio\">matériel tissulaire</span> — indispensable aux <span class=\"kw-bio\">analyses moléculaires</span> ultérieures et <span class=\"kw-alerte\">impossible après fixation au formol</span>.</p>\n      <div class=\"callout callout-danger\">⚠️ <strong>Tumeurs à adresser impérativement à l'état frais</strong> (cryopréservation) :\n        <ul>\n          <li><span class=\"kw-etio\">Tumeur pédiatrique</span></li>\n          <li>Suspicion de <span class=\"kw-etio\">lymphome</span></li>\n          <li><span class=\"kw-etio\">Sarcome</span></li>\n        </ul>\n      </div>\n      <p>Plus largement, l'<span class=\"kw-def\">état frais</span> (sans fixateur) est requis dans <strong>quatre situations</strong> :</p>\n      <ul>\n        <li><strong><span class=\"kw-bio\">Examen extemporané</span></strong> (réponse peropératoire).</li>\n        <li><strong>Recherche de <span class=\"kw-bio\">graisses</span></strong> dans le tissu (l'inclusion en paraffine dissout les graisses).</li>\n        <li><strong><span class=\"kw-bio\">Immunofluorescence directe</span></strong> (<span class=\"kw-ttt\">biopsie</span> cutanée, rénale, typage d'amylose).</li>\n        <li><strong>Conservation de matériel tissulaire <span class=\"kw-bio\">congelé</span></strong> avec <span class=\"kw-bio\">cryopréservation</span>, à but sanitaire : <span class=\"kw-etio\">tumeur pédiatrique</span>, <span class=\"kw-etio\">lymphome</span>, <span class=\"kw-etio\">sarcome</span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\">⚠️ Un prélèvement frais non fixé doit parvenir au laboratoire en <span class=\"kw-chiffre\">&lt; 30 minutes</span> (risque d'<span class=\"kw-alerte\">autolyse</span> / <span class=\"kw-alerte\">dessiccation</span>).</div>","frequence":2}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"liensGlobaux":[{"href":"https://www.sfpathol.org/564-manuel-introduction.html","label":"Collège d’anatomie et cytologie pathologiques (SFP) — manuel d’introduction"}],"cards":[{"i":"1bc33449f480","n":293,"o":"293-3","u":"Examens complémentaires","t":"Savoir remplir la fiche de renseignements","q":"Quelles sont les informations relatives au patient et aux professionnels de santé qui doivent figurer sur la fiche de renseignements d'un prélèvement ?","a":"<ul><li><strong>Identité du patient</strong> : nom, prénom, date de naissance, sexe, adresse et/ou identifiant hospitalier.</li><li><strong>Identité du médecin prescripteur</strong> : nom, prénom, structure de soin et service, identifiants professionnels.</li><li><strong>Identité du préleveur</strong> : mêmes informations que le prescripteur, si différent.</li></ul>"},{"i":"97d0ad98f3b2","n":293,"o":"293-3","u":"Examens complémentaires","t":"Savoir remplir la fiche de renseignements","q":"Quelles informations spécifiques au prélèvement lui-même et aux analyses souhaitées doivent être renseignées sur la fiche ?","a":"<ul><li><strong>Date et heure du prélèvement</strong>.</li><li><strong>Nature du prélèvement</strong> (ex: biopsie, cytoponction, pièce opératoire).</li><li><strong>Siège du ou des échantillons</strong> (localisation anatomique précise).</li><li><strong>Renseignements cliniques pertinents</strong> (pour orienter l'interprétation morphologique).</li><li><strong>Recherches particulières demandées</strong> (ex: technique ou marqueur ciblé).</li><li><strong>Type d'analyse souhaité</strong> sur le prélèvement (ex: examen anatomopathologique, examen cytobactériologique).</li><li><strong>Caractère urgent</strong> éventuel de la demande.</li></ul>"},{"i":"9ba13a33745c","n":293,"o":"293-3","u":"Examens complémentaires","t":"Savoir remplir la fiche de renseignements","q":"Quel est l'objectif principal de la fiche de renseignements accompagnant un prélèvement tissulaire ou cellulaire ?","a":"<p>La fiche de renseignements a pour objectif de fournir au <strong>pathologiste</strong> les <strong>informations indispensables</strong> à l'interprétation du prélèvement. Elle ne contient aucune analyse en elle-même.</p>"}]};